const data = $input.first().json;
const refreshed = data.refreshed_count ?? data.refreshed ?? data.updated_count ?? 0;
const failed = data.failed_count ?? data.failed ?? 0;
const skipped = data.skipped_count ?? data.skipped ?? 0;
const failures = data.failures || data.failed_urls || data.errors || [];

function cleanUrl(value) {
  try {
    const parsed = new URL(String(value));
    parsed.hash = '';
    parsed.search = '';
    return parsed.toString();
  } catch (error) {
    return String(value || 'unknown-url').slice(0, 120);
  }
}

function cleanError(value) {
  return String(value || 'unknown error')
    .replace(/(api[_-]?key|token|secret|password)=([^\s&]+)/gi, '$1=REDACTED')
    .slice(0, 140);
}

const topFailures = Array.isArray(failures)
  ? failures.slice(0, 5).map((failure) => {
      if (typeof failure === 'string') return `- ${cleanError(failure)}`;
      return `- ${cleanUrl(failure.url || failure.product_url)}: ${cleanError(failure.error || failure.reason || failure.message)}`;
    })
  : [];

return [{
  json: {
    chatId: String($env.FOUNDER_TELEGRAM_CHAT_ID || ''),
    reply: [
      'Nightly Saudi known URL refresh complete.',
      `Refreshed: ${refreshed}`,
      `Failed: ${failed}`,
      `Skipped: ${skipped}`,
      topFailures.length ? `Top failures:\n${topFailures.join('\n')}` : 'Top failures: none reported',
      'Reminder: Noon Saudi and Amazon.sa refresh may be policy-gated.'
    ].join('\n')
  }
}];
